def sat(x, a, k):
    from scipy.special import erf
    if k == 'tanh':
        return np.tanh(a * x)
    if k == 'erf':
        return erf(a * x)
    if k == 'sin':
        return np.sin(a * x)
    if k == 'rat':
        return x / (1 + (a * x) ** 2)
    if k == 'soft':
        return x / np.sqrt(1 + (a * x) ** 2)
    if k == 'atan':
        return np.arctan(a * x)

def get(s):
    from scipy.optimize import least_squares
    tr = s['train']
    x = np.r_[tr['x'], s['test']['x']]
    (u, v) = (s['panel_a'][k] for k in ('u', 'v'))
    A = poly(u)
    keep = np.ones(len(u), bool)
    for _ in range(12):
        w = fit(A[keep], v[keep])
        e = np.linalg.norm(A @ w - v, axis=1)
        new = e < max(0.001, 3 * np.median(e))
        if new.sum() < 18 or np.array_equal(new, keep):
            break
        keep = new
    z = np.linalg.solve(w[1:5].T, (x - w[0]).T).T
    for i in range(20):
        K = w[5:9]
        J = w[1:5] + np.roll(z, -1, axis=1)[:, :, None] * K + np.roll(z[:, :, None] * K, 1, axis=1) + 3 * z[:, :, None] ** 2 * w[9:13]
        z -= np.clip(np.linalg.solve(J.transpose(0, 2, 1), (poly(z) @ w - x)[..., None])[..., 0], -0.4, 0.4)
    (u, v) = (s['panel_b'][k] for k in ('u', 'v'))

    def H(x, q):
        return D(np.sign(x) * np.maximum(abs(x) - q[0], 0) ** q[1])

    def r(q):
        F = H(u, q)
        return (F @ fit(F, v) - v).ravel()
    q = least_squares(r, [0.35, 1.5], bounds=([0.1, 0.5], [0.7, 3])).x
    b = H(z, q) @ fit(H(u, q), v)
    p = s['panel_c']
    u = p['u']
    K = fit(poly(u), p['v1'])
    c = lambda x: poly(x) @ K
    t = s['eval_times']
    T = tr['traj'].T

    def F(q):
        return -np.expm1(-t[:, None] * q)

    def e(q):
        f = F(q)
        return (f @ fit(f, T) - T).ravel()
    q = least_squares(e, [1.8, 0.42], bounds=([1.0, 0.15], [3.0, 0.85])).x
    f = F(q)
    targets = np.c_[tr['y'], fit(f, T).T]
    return (z, b, c, f, targets, (w, keep, x - poly(z) @ w, u, p['v1'], p['v2'], q, e(q)))

def models(s, verbose=False):
    from scipy.optimize import least_squares
    (z0, b0, c, f, Y, aux) = get(s)
    keep = aux[1]
    (u, v) = [s['panel_a'][k][keep] for k in ['u', 'v']]
    x = np.r_[s['train']['x'], s['test']['x']]
    cand = []
    for k in ['tanh', 'erf', 'sin', 'rat', 'soft', 'atan']:
        for typ in [0, 1, 2]:

            def F(z, a, k=k, typ=typ):
                h = sat(z, a, k)
                return D(np.c_[z, h] if typ == 0 else np.c_[z, h, z * z] if typ == 1 else np.c_[z, h, z * np.roll(z, -1, axis=1)])

            def e(a):
                A = F(u, a)
                return (A @ fit(A, v) - v).ravel()
            r = least_squares(e, 1.25, bounds=(0.1, 5))
            cand.append((np.mean(r.fun ** 2) ** 0.5, k, typ, r.x, F))
    cand.sort(key=lambda t: t[0])
    (ee, k, typ, a, F) = cand[0]
    w = fit(F(u, a), v)
    z = np.array([least_squares(lambda zz: (F(zz[None, :], a) @ w - xx).ravel(), zz, bounds=(-3, 3)).x for (xx, zz) in zip(x, z0)])
    if verbose:
        print('A', [(round(e, 7), k, t, a.round(5)) for (e, k, t, a, _) in cand[:10]], 'z', z.min(), z.max(), 'inverse', np.max(abs(F(z, a) @ w - x)), 'w', w.round(4), flush=True)
    (u, v) = [s['panel_b'][k] for k in ['u', 'v']]
    H = lambda z: D(np.sign(z) * np.maximum(abs(z) - 0.35, 0) ** 1.5)
    B = lambda z: H(z) @ fit(H(u), v)
    (u, h) = [s['panel_c'][k] for k in ['u', 'v2']]
    cand = []
    for k in ['tanh', 'erf', 'sin', 'rat', 'soft', 'atan']:
        for typ in range(4):

            def F(z, a, k=k, typ=typ):
                h = sat(z, a, k)
                return D([h, h * h][0] if typ == 0 else np.c_[z, h] if typ == 1 else np.c_[h, h * h] if typ == 2 else np.c_[z, h, h * h])

            def e(a):
                A = F(u, a)
                return (A @ fit(A, h) - h).ravel()
            r = least_squares(e, 1.25, bounds=(0.1, 5))
            cand.append((np.mean(r.fun ** 2) ** 0.5, k, typ, r.x, F))
    cand.sort(key=lambda t: t[0])
    (ee, k, typ, a, F) = cand[0]
    w = fit(F(u, a), h)
    E = lambda z: F(z, a) @ w
    if verbose:
        print('C2', [(round(e, 7), k, t, a.round(5)) for (e, k, t, a, _) in cand[:10]], w.round(4), flush=True)
    return (z, B, c, E, f, Y)
